files.content:
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1e1b2e;
  --card-bg: #2d2640;
  --pixel-border: #0d0b14;
  --accent-work: #ff5e7e;
  --accent-break: #4deeea;
  --text-main: #f5f2f9;
  --text-muted: #a39bb8;
  --btn-shadow: #141120;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--text-main);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 440px;
  display: flex;
  justify-content: center;
}

.pixel-card {
  width: 100%;
  background-color: var(--card-bg);
  border: 4px solid var(--pixel-border);
  box-shadow:
    8px 8px 0px 0px var(--pixel-border),
    inset -4px -4px 0px 0px rgba(0, 0, 0, 0.3),
    inset 4px 4px 0px 0px rgba(255, 255, 255, 0.1);
  padding: 24px 20px;
  text-align: center;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 8px;
}

.app-title {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--text-main);
  text-shadow: 2px 2px 0px var(--pixel-border);
}

.mode-badge {
  font-size: 14px;
  font-weight: 700;
  padding: 4px 10px;
  border: 3px solid var(--pixel-border);
  box-shadow: 2px 2px 0px 0px var(--pixel-border);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.mode-badge.work {
  background-color: var(--accent-work);
  color: #1a060d;
}

.mode-badge.break {
  background-color: var(--accent-break);
  color: #032120;
}

.timer-display-wrap {
  background-color: #121019;
  border: 4px solid var(--pixel-border);
  box-shadow: inset 4px 4px 0px 0px rgba(0, 0, 0, 0.5);
  padding: 28px 16px;
  margin-bottom: 24px;
}

.timer-display {
  font-size: 48px;
  font-weight: 900;
  letter-spacing: 4px;
  color: var(--accent-work);
  text-shadow: 0 0 10px rgba(255, 94, 126, 0.3);
}

.timer-display.break-mode {
  color: var(--accent-break);
  text-shadow: 0 0 10px rgba(77, 238, 234, 0.3);
}

.cycle-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  padding: 8px 12px;
  background: rgba(0, 0, 0, 0.2);
  border: 2px solid var(--pixel-border);
}

.cycle-label {
  font-size: 16px;
  font-weight: 700;
}

.cycle-dots {
  display: flex;
  gap: 8px;
}

.dot {
  width: 14px;
  height: 14px;
  background: #463c63;
  border: 2px solid var(--pixel-border);
  display: inline-block;
}

.dot.active {
  background: var(--accent-work);
  box-shadow: 0 0 4px var(--accent-work);
}

.controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.btn {
  appearance: none;
  border: 3px solid var(--pixel-border);
  padding: 12px 6px;
  font-family: inherit;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 1px;
  cursor: pointer;
  box-shadow: 4px 4px 0px 0px var(--btn-shadow);
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.btn:focus-visible {
  outline: 3px solid var(--accent-break);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px 0px var(--btn-shadow);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: 2px 2px 0px 0px var(--btn-shadow);
  transform: translate(1px, 1px);
}

.btn-primary {
  background-color: var(--accent-work);
  color: #1a060d;
}

.btn-primary:hover:not(:disabled) {
  filter: brightness(1.1);
}

.btn-secondary {
  background-color: var(--accent-break);
  color: #032120;
}

.btn-secondary:hover:not(:disabled) {
  filter: brightness(1.1);
}

.btn-outline {
  background-color: #4a3e6a;
  color: var(--text-main);
}

.btn-outline:hover:not(:disabled) {
  background-color: #56487a;
}

.card-footer {
  border-top: 2px dashed rgba(255, 255, 255, 0.15);
  padding-top: 14px;
}

.hint-text {
  font-size: 13px;
  color: var(--text-muted);
}

@media (max-width: 380px) {
  .timer-display {
    font-size: 38px;
  }
  .btn {
    font-size: 14px;
    padding: 10px 4px;
  }
}

(() => {
  const WORK_SECONDS = 25 * 60;
  const SHORT_BREAK_SECONDS = 5 * 60;
  const LONG_BREAK_SECONDS = 15 * 60;
  const SESSIONS_BEFORE_LONG_BREAK = 4;

  let currentMode = 'WORK'; // 'WORK' or 'BREAK'
  let completedWorkSessions = 0;
  let currentCycle = 1;
  let remainingSeconds = WORK_SECONDS;
  let timerInterval = null;
  let expectedEndTime = null;

  const timerDisplay = document.getElementById('timer-display');
  const modeLabel = document.getElementById('mode-label');
  const cycleCountSpan = document.getElementById('cycle-count');
  const cycleDotsContainer = document.getElementById('cycle-dots');
  const btnStart = document.getElementById('btn-start');
  const btnPause = document.getElementById('btn-pause');
  const btnReset = document.getElementById('btn-reset');

  function formatTime(totalSeconds) {
    const safeSec = Math.max(0, Math.ceil(totalSeconds));
    const minutes = Math.floor(safeSec / 60);
    const seconds = safeSec % 60;
    const mStr = String(minutes).padStart(2, '0');
    const sStr = String(seconds).padStart(2, '0');
    return `${mStr}:${sStr}`;
  }

  function renderUI() {
    const formatted = formatTime(remainingSeconds);
    timerDisplay.textContent = formatted;
    document.title = `${formatted} - ${currentMode === 'WORK' ? 'Work' : 'Break'} | Pixel Focus`;

    if (currentMode === 'WORK') {
      modeLabel.textContent = 'Work';
      modeLabel.className = 'mode-badge work';
      timerDisplay.classList.remove('break-mode');
    } else {
      const isLongBreak = (completedWorkSessions % SESSIONS_BEFORE_LONG_BREAK === 0);
      modeLabel.textContent = isLongBreak ? 'Long Break' : 'Break';
      modeLabel.className = 'mode-badge break';
      timerDisplay.classList.add('break-mode');
    }

    cycleCountSpan.textContent = String(currentCycle);

    const dots = cycleDotsContainer.querySelectorAll('.dot');
    dots.forEach((dot, index) => {
      if (index < currentCycle) {
        dot.classList.add('active');
      } else {
        dot.classList.remove('active');
      }
    });
  }

  function nextMode() {
    if (currentMode === 'WORK') {
      completedWorkSessions += 1;
      currentMode = 'BREAK';
      if (completedWorkSessions % SESSIONS_BEFORE_LONG_BREAK === 0) {
        remainingSeconds = LONG_BREAK_SECONDS;
      } else {
        remainingSeconds = SHORT_BREAK_SECONDS;
      }
    } else {
      currentMode = 'WORK';
      currentCycle = (completedWorkSessions % SESSIONS_BEFORE_LONG_BREAK) + 1;
      remainingSeconds = WORK_SECONDS;
    }
    expectedEndTime = Date.now() + (remainingSeconds * 1000);
    renderUI();
  }

  function tick() {
    const now = Date.now();
    remainingSeconds = Math.max(0, (expectedEndTime - now) / 1000);
    if (remainingSeconds <= 0) {
      nextMode();
    } else {
      renderUI();
    }
  }

  function startTimer() {
    if (timerInterval) return;
    expectedEndTime = Date.now() + (remainingSeconds * 1000);
    timerInterval = setInterval(tick, 200);
    btnStart.disabled = true;
    btnPause.disabled = false;
  }

  function pauseTimer() {
    if (!timerInterval) return;
    clearInterval(timerInterval);
    timerInterval = null;
    if (expectedEndTime) {
      remainingSeconds = Math.max(0, (expectedEndTime - Date.now()) / 1000);
    }
    btnStart.disabled = false;
    btnPause.disabled = true;
    renderUI();
  }

  function resetTimer() {
    pauseTimer();
    currentMode = 'WORK';
    completedWorkSessions = 0;
    currentCycle = 1;
    remainingSeconds = WORK_SECONDS;
    renderUI();
  }

  btnStart.addEventListener('click', startTimer);
  btnPause.addEventListener('click', pauseTimer);
  btnReset.addEventListener('click', resetTimer);

  window.addEventListener('keydown', (event) => {
    if (event.target && ['INPUT', 'TEXTAREA'].includes(event.target.tagName)) {
      return;
    }
    if (event.code === 'Space') {
      event.preventDefault();
      if (timerInterval) {
        pauseTimer();
      } else {
        startTimer();
      }
    } else if (event.key === 'r' || event.key === 'R') {
      resetTimer();
    }
  });

  renderUI();
})();
